import React, { useState } from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { useLang } from '../LangContext';

const LANGS = [{ code: 'en', label: 'EN' }, { code: 'am', label: 'አማ' }, { code: 'or', label: 'OR' }];

const C = {
  primary: '#f97316',
  bg: '#0a0a0a',
  bg2: '#111111',
  card: '#171717',
  border: '#262626',
  borderLight: '#1a1a1a',
  white: '#ffffff',
  gray: '#a3a3a3',
  red: '#ef4444',
};

export default function Navbar() {
  const [open, setOpen] = useState(false);
  const navigate = useNavigate();
  const { lang, switchLang, t } = useLang();
  const user = JSON.parse(localStorage.getItem('user') || 'null');

  const logout = () => {
    localStorage.removeItem('userToken');
    localStorage.removeItem('user');
    navigate('/');
    window.location.reload();
  };

  const links = [
    { to: '/', label: t.home, end: true },
    { to: '/clients', label: t.clients },
    { to: '/news', label: t.news },
    { to: '/about', label: t.about },
    { to: '/contact', label: t.contact },
  ];

  const linkStyle = (isActive) => ({
    padding: '8px 13px',
    color: isActive ? C.primary : C.gray,
    fontSize: 14,
    borderRadius: 8,
    transition: 'color 0.2s',
    fontWeight: isActive ? 600 : 400,
  });

  return (
    <nav style={{
      background: 'rgba(10,10,10,0.97)',
      backdropFilter: 'blur(12px)',
      borderBottom: `1px solid ${C.borderLight}`,
      position: 'sticky',
      top: 0,
      zIndex: 100,
    }}>
      <div style={{
        maxWidth: 1200, margin: '0 auto',
        padding: '0 24px', height: 64,
        display: 'flex', alignItems: 'center',
        justifyContent: 'space-between', gap: 16,
      }}>
        {/* Logo */}
        <NavLink to="/" style={{ fontSize: 20, fontWeight: 900, color: C.white, flexShrink: 0 }}>
          All <span style={{ color: C.primary }}>Things</span>
        </NavLink>

        {/* Desktop nav */}
        <div className="nav-links">
          {links.map(({ to, label, end }) => (
            <NavLink key={to} to={to} end={end}
              style={({ isActive }) => linkStyle(isActive)}>
              {label}
            </NavLink>
          ))}
          {user ? (
            <>
              <NavLink to="/dashboard" style={({ isActive }) => linkStyle(isActive)}>
                👤 {user.full_name?.split(' ')[0]}
              </NavLink>
              <button onClick={logout} style={{
                padding: '8px 13px', background: 'none', border: 'none',
                color: C.red, fontSize: 14, cursor: 'pointer',
              }}>
                {t.signOut}
              </button>
            </>
          ) : (
            <>
              <NavLink to="/login" style={({ isActive }) => linkStyle(isActive)}>
                {t.signIn}
              </NavLink>
              <NavLink to="/register" style={{
                marginLeft: 6, padding: '9px 20px',
                background: C.primary, color: '#000',
                borderRadius: 8, fontWeight: 700, fontSize: 14,
              }}>
                {t.register}
              </NavLink>
            </>
          )}
          {/* Language switcher */}
          <div className="lang-switcher" style={{ marginLeft: 10 }}>
            {LANGS.map(l => (
              <button key={l.code}
                className={`lang-btn${lang === l.code ? ' active' : ''}`}
                onClick={() => switchLang(l.code)}>
                {l.label}
              </button>
            ))}
          </div>
        </div>

        {/* Mobile: lang + burger */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <div className="lang-switcher">
            {LANGS.map(l => (
              <button key={l.code}
                className={`lang-btn${lang === l.code ? ' active' : ''}`}
                onClick={() => switchLang(l.code)}>
                {l.label}
              </button>
            ))}
          </div>
          <button className="nav-burger" onClick={() => setOpen(!open)}>
            {open ? '✕' : '☰'}
          </button>
        </div>
      </div>

      {/* Mobile dropdown menu */}
      {open && (
        <div style={{
          borderTop: `1px solid ${C.borderLight}`,
          padding: '8px 20px 20px',
          background: C.bg2,
        }}>
          {links.map(({ to, label, end }) => (
            <NavLink key={to} to={to} end={end}
              onClick={() => setOpen(false)}
              style={({ isActive }) => ({
                display: 'block', padding: '12px 4px',
                color: isActive ? C.primary : C.gray,
                fontSize: 15,
                borderBottom: `1px solid ${C.borderLight}`,
              })}>
              {label}
            </NavLink>
          ))}

          {user ? (
            <>
              <NavLink to="/dashboard" onClick={() => setOpen(false)} style={{
                display: 'block', padding: '12px 4px',
                color: C.gray, fontSize: 15,
                borderBottom: `1px solid ${C.borderLight}`,
              }}>
                👤 {t.myDashboard}
              </NavLink>
              <button onClick={logout} style={{
                display: 'block', width: '100%', textAlign: 'left',
                padding: '12px 4px', background: 'none', border: 'none',
                color: C.red, fontSize: 15, cursor: 'pointer',
              }}>
                {t.signOut}
              </button>
            </>
          ) : (
            <div style={{ display: 'flex', gap: 10, marginTop: 16 }}>
              <NavLink to="/login" onClick={() => setOpen(false)} style={{
                flex: 1, textAlign: 'center', padding: '11px',
                background: C.card, color: C.white,
                borderRadius: 8, border: `1px solid ${C.border}`,
                fontWeight: 600, fontSize: 14,
              }}>
                {t.signIn}
              </NavLink>
              <NavLink to="/register" onClick={() => setOpen(false)} style={{
                flex: 1, textAlign: 'center', padding: '11px',
                background: C.primary, color: '#000',
                borderRadius: 8, fontWeight: 700, fontSize: 14,
              }}>
                {t.register}
              </NavLink>
            </div>
          )}
        </div>
      )}
    </nav>
  );
}
